//! Language metadata types for REPL introspection
//!
//! These types are generated by the `language!` macro and provide
//! static metadata about a language's types, terms, equations, rewrites, and
//! runtime backend capabilities.
//! The REPL uses this to display the `info` command output.
//!
//! The metadata also serves as the **bridge between the macro and the
//! stochastic simulator** ([`mettail_simulation::LanguageStateMachine`]).
//! Every field that the simulator needs — including runtime backend evidence
//! and the guard configuration from the `guards { }` block (theories,
//! channels, built-in predicates, connectives) — is carried through this trait
//! with default-empty methods.

use crate::language::RuntimeBackend;

/// Trait for accessing static language metadata
///
/// Implemented by generated `{LanguageName}Metadata` structs.
pub trait LanguageMetadata: 'static + Send + Sync {
    /// The language name (e.g., "RhoCalc")
    fn name(&self) -> &'static str;

    /// Stable compiler-facing fingerprint of the macro-expanded `LanguageDef`.
    ///
    /// This is implementation identity data used to reject backend plans derived
    /// from a different generated definition. It is not intended for user
    /// display.
    fn definition_fingerprint(&self) -> Option<&'static str> {
        None
    }

    /// Raw `language!` body source from which this language was generated.
    ///
    /// When present, this is the verbatim token-stream text of the macro
    /// invocation body (everything inside `language! { ... }`). Feeding it to
    /// `mettail_ast::auto_inject::reconstruct_language_def` replays the exact
    /// macro-time augmentation (composition + auto-injection) and reproduces a
    /// `LanguageDef` that fingerprints identically to
    /// [`Self::definition_fingerprint`]. This enables runtime reconstruction of
    /// the real augmented definition (e.g. for per-language Dovetail/Rho backend
    /// planning) instead of fingerprint-spoofing shims.
    ///
    /// Defaults to `None` so hand-written metadata impls remain valid.
    fn definition_source(&self) -> Option<&'static str> {
        None
    }

    /// Derived automata-facing model for parser/runtime planning.
    ///
    /// This is the stable metadata boundary that parser tables, Dovetail rule
    /// inventories, and RhoNet planning can share without reparsing display
    /// strings or depending on generated Rust control flow. Generated metadata
    /// implementations may override it later with denser tables; the default is
    /// intentionally derived from the existing static metadata slices so every
    /// current language has a sound model immediately.
    fn automata_model(&self) -> LanguageAutomataModel {
        LanguageAutomataModel {
            definition_fingerprint: self.definition_fingerprint(),
            categories: self.types(),
            terms: self.terms(),
            equations: self.equations(),
            rewrites: self.rewrites(),
            builtin_predicates: self.builtin_predicates(),
            theories: self.theories(),
            channels: self.channels(),
            join_patterns: self.join_patterns(),
        }
    }

    /// Type definitions (first is primary)
    fn types(&self) -> &'static [TypeDef];

    /// Term (constructor) definitions
    fn terms(&self) -> &'static [TermDef];

    /// Equation definitions
    fn equations(&self) -> &'static [EquationDef];

    /// Rewrite rule definitions
    fn rewrites(&self) -> &'static [RewriteDef];

    /// Runtime backends that the generated language advertises statically.
    ///
    /// A backend capability is executable evidence, not a planning note. A
    /// language should list a backend here only when its `Language`
    /// implementation can route that backend without silently falling back to a
    /// different backend. Runtime wrappers that install a backend for a
    /// concrete value should expose that through
    /// [`crate::Language::runtime_backend_capabilities`] instead of mutating
    /// this static table.
    fn runtime_backends(&self) -> &'static [BackendCapabilityDef] {
        NO_RUNTIME_BACKEND_CAPABILITIES
    }

    /// Custom logic relation definitions
    fn logic_relations(&self) -> &'static [LogicRelationDef] {
        &[]
    }

    /// Custom logic rule definitions
    fn logic_rules(&self) -> &'static [LogicRuleDef] {
        &[]
    }

    // ─────────────────────────────────────────────────────────────────────
    // Guard configuration metadata (Sim-A / design doc §2A)
    //
    // These methods expose the contents of a language's `guards { }` block
    // so that the simulator, REPL, and external tooling can introspect
    // which predicates, theories, and channel topologies a language
    // declares. All default to empty — existing language definitions
    // without a `guards { }` block work unchanged.
    // ─────────────────────────────────────────────────────────────────────

    /// Built-in predicate declarations from the `guards { }` block.
    ///
    /// Each entry describes one direct predicate item with its name,
    /// surface syntax form, and optional selectivity / cost annotations.
    /// Returns an empty slice when the language has no `guards { }`
    /// block or declares no direct predicates.
    fn builtin_predicates(&self) -> &'static [BuiltinPredicateDef] {
        &[]
    }

    /// Constraint theory registrations from `guards { theories { } }`.
    ///
    /// Each entry maps a local registration name (e.g., `arithmetic`) to
    /// the theory type (e.g., `PresburgerAlgebra`) and the grammar
    /// categories the theory handles. Returns an empty slice when no
    /// theories are registered.
    fn theories(&self) -> &'static [TheoryDef] {
        &[]
    }

    /// Channel category declarations from `guards { channels { } }`.
    ///
    /// Each entry names a grammar category that serves as a communication
    /// channel for multi-channel guard dispatch. Returns an empty slice
    /// when no `channels { }` sub-block is declared.
    fn channels(&self) -> &'static [ChannelDef] {
        &[]
    }

    /// Join pattern declarations from `guards { channels { join … } }`.
    ///
    /// Each entry names a constructor and the channel categories its
    /// channel-binding parameters reference. Returns an empty slice when
    /// no join patterns are declared.
    fn join_patterns(&self) -> &'static [JoinPatternDef] {
        &[]
    }

    /// Logical connective declarations from `guards { connectives { } }`.
    ///
    /// Each entry maps a connective role (`and`, `or`, `not`, `entails`,
    /// `implied_by`, `iff`, `forall`, `exists`) to its surface keyword
    /// spellings. Returns an empty slice when no `connectives { }`
    /// sub-block is declared.
    fn connectives(&self) -> &'static [ConnectiveDef] {
        &[]
    }

    /// Get the primary type (first type in the language)
    fn primary_type(&self) -> &'static TypeDef {
        self.types()
            .first()
            .expect("language must have at least one type")
    }

    /// Get terms for a specific type
    fn terms_for_type(&self, type_name: &str) -> Vec<&'static TermDef> {
        self.terms()
            .iter()
            .filter(|t| t.type_name == type_name)
            .collect()
    }
}

/// Static runtime backend installed for a generated language.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BackendCapabilityDef {
    /// Backend exposed through `Language::run_backend_report`.
    pub backend: RuntimeBackend,

    /// Whether this backend is the language's user-facing default.
    pub is_default: bool,
}

pub const NO_RUNTIME_BACKEND_CAPABILITIES: &[BackendCapabilityDef] = &[];

/// Runtime-neutral automata model derived from generated language metadata.
///
/// The model deliberately stores references to the existing generated metadata
/// slices. It is therefore cheap to construct, object-safe through
/// [`LanguageMetadata::automata_model`], and stable enough for downstream
/// planner code to depend on while denser parser/Rho tables are introduced.
#[derive(Debug, Clone, Copy)]
pub struct LanguageAutomataModel {
    pub definition_fingerprint: Option<&'static str>,
    pub categories: &'static [TypeDef],
    pub terms: &'static [TermDef],
    pub equations: &'static [EquationDef],
    pub rewrites: &'static [RewriteDef],
    pub builtin_predicates: &'static [BuiltinPredicateDef],
    pub theories: &'static [TheoryDef],
    pub channels: &'static [ChannelDef],
    pub join_patterns: &'static [JoinPatternDef],
}

impl LanguageAutomataModel {
    /// Number of semantic rules that can contribute to runtime rewriting.
    pub fn semantic_rule_count(&self) -> usize {
        self.equations.len() + self.rewrites.len()
    }

    /// Number of declared guard/predicate obligations visible from metadata.
    pub fn guard_surface_count(&self) -> usize {
        self.builtin_predicates.len()
            + self.theories.len()
            + self.channels.len()
            + self.join_patterns.len()
    }

    /// Whether any runtime semantic rule is guarded.
    pub fn has_guarded_runtime_rules(&self) -> bool {
        self.equations.iter().any(|equation| equation.is_guarded)
            || self.rewrites.iter().any(|rewrite| rewrite.is_guarded)
    }

    /// Whether the model has enough identity data for fingerprint-checked
    /// backend plans.
    pub fn has_definition_identity(&self) -> bool {
        self.definition_fingerprint
            .is_some_and(|fingerprint| !fingerprint.trim().is_empty())
    }
}

/// Definition of a type (category) in the language
#[derive(Debug, Clone, Copy)]
pub struct TypeDef {
    /// Type name (e.g., "Proc", "Name")
    pub name: &'static str,

    /// Native Rust type if this is a primitive (e.g., "i32")
    pub native_type: Option<&'static str>,

    /// Whether this is the primary type (first in declaration order)
    pub is_primary: bool,
}

/// Definition of a term (constructor) in the language
#[derive(Debug, Clone, Copy)]
pub struct TermDef {
    /// Constructor name (e.g., "PInput", "NQuote")
    pub name: &'static str,

    /// The type this constructor produces (e.g., "Proc")
    pub type_name: &'static str,

    /// User syntax representation (e.g., "n?x.{p}")
    pub syntax: &'static str,

    /// Optional description (from doc comments)
    pub description: Option<&'static str>,

    /// Field definitions
    pub fields: &'static [FieldDef],
}

/// Definition of a field in a term constructor
#[derive(Debug, Clone, Copy)]
pub struct FieldDef {
    /// Field name (e.g., "n", "p", "x")
    pub name: &'static str,

    /// Field type (e.g., "Name", "Proc", "[Name -> Proc]")
    pub ty: &'static str,

    /// Whether this field is a binder
    pub is_binder: bool,
}

/// Definition of an equation (axiom)
#[derive(Debug, Clone, Copy)]
pub struct EquationDef {
    /// Freshness conditions (e.g., ["x # P"])
    pub conditions: &'static [&'static str],

    /// Left-hand side in user syntax
    pub lhs: &'static str,

    /// Right-hand side in user syntax
    pub rhs: &'static str,

    /// Whether this equation has a `BehavioralGuard` premise.
    ///
    /// Set by the macro codegen when the equation's premise list contains
    /// a `Premise::BehavioralGuard(...)` entry. The simulator uses this to
    /// exclude guarded equations from its unconditional-axiom count and
    /// to surface them to guard-aware invariants.
    pub is_guarded: bool,
}

/// Definition of a rewrite rule
#[derive(Debug, Clone, Copy)]
pub struct RewriteDef {
    /// Optional rule name (e.g., "communication")
    pub name: Option<&'static str>,

    /// Freshness conditions
    pub conditions: &'static [&'static str],

    /// Congruence premise: if (S, T) then S ~> T
    pub premise: Option<(&'static str, &'static str)>,

    /// Left-hand side in user syntax
    pub lhs: &'static str,

    /// Right-hand side in user syntax
    pub rhs: &'static str,

    /// Whether this rewrite rule has a guard premise.
    ///
    /// Set by the macro codegen when the rewrite's premise list contains a
    /// user-authored `Premise::BehavioralGuard(...)` entry or a generated
    /// `Premise::SyntheticInjGuard { .. }` entry. The simulator uses this
    /// field to identify guarded rewrites for guard-aware invariants and
    /// scheduling.
    pub is_guarded: bool,
}

impl RewriteDef {
    /// Check if this is a congruence rule (has a premise)
    pub fn is_congruence(&self) -> bool {
        self.premise.is_some()
    }

    /// Check if this is a base rewrite (no premise)
    pub fn is_base(&self) -> bool {
        self.premise.is_none()
    }
}

/// Definition of a custom logic relation
#[derive(Debug, Clone, Copy)]
pub struct LogicRelationDef {
    /// Relation name (e.g., "path", "can_send")
    pub name: &'static str,

    /// Parameter type names (e.g., ["Proc", "Proc"])
    pub param_types: &'static [&'static str],

    /// Optional description (from comment)
    pub description: Option<&'static str>,
}

/// Definition of a custom logic rule
#[derive(Debug, Clone, Copy)]
pub struct LogicRuleDef {
    /// The rule in Ascent syntax (formatted for display)
    pub rule: &'static str,
}

// ═════════════════════════════════════════════════════════════════════════════
// Guard configuration metadata (Sim-A / design doc §2A)
// ═════════════════════════════════════════════════════════════════════════════

/// A built-in predicate declaration from the `guards { }` block.
///
/// Describes one direct predicate item with its name, surface syntax
/// form, and optional selectivity / cost annotations from `@[…]`.
///
/// Example source:
/// ```text
/// guards {
///     eq . x, y |- x "==" y @[selectivity(0.1), cost(2)] ;
/// }
/// ```
#[derive(Debug, Clone, Copy)]
pub struct BuiltinPredicateDef {
    /// The predicate's canonical name (e.g., `"eq"`, `"gt"`, `"fresh"`).
    pub name: &'static str,

    /// A human-readable rendering of one of the predicate's surface
    /// syntax forms. When a predicate declares multiple alternative
    /// syntax forms via `|`, this field holds the *first* form in
    /// declaration order.
    pub syntax: &'static str,

    /// The `@[selectivity(s)]` annotation value, if any. `None` when
    /// the predicate uses the pipeline's heuristic default.
    pub selectivity: Option<f64>,

    /// The `@[cost(c)]` annotation value, if any. `None` when the
    /// predicate uses the pipeline's heuristic default.
    pub cost: Option<u32>,
}

/// A constraint theory registration from `guards { theories { } }`.
///
/// Example source:
/// ```text
/// guards {
///     theories {
///         arithmetic = PresburgerAlgebra for [Int];
///     }
/// }
/// ```
#[derive(Debug, Clone, Copy)]
pub struct TheoryDef {
    /// The grammar-author-chosen local name for this registration
    /// (e.g., `"arithmetic"`, `"patterns"`, `"types"`).
    pub name: &'static str,

    /// The stringified Rust type implementing the theory
    /// (e.g., `"PresburgerAlgebra"`, `"UnificationTheory"`).
    pub theory_type: &'static str,

    /// The grammar categories the theory handles, from the `for [...]`
    /// clause. Empty slice when the clause is omitted (meaning "all").
    pub handled_types: &'static [&'static str],
}

/// A channel category declaration from `guards { channels { } }`.
#[derive(Debug, Clone, Copy)]
pub struct ChannelDef {
    /// The grammar category that serves as a communication channel.
    pub category: &'static str,
}

/// A join pattern declaration from `guards { channels { join … } }`.
///
/// Example source:
/// ```text
/// guards {
///     channels {
///         channel Name;
///         join PGuardedInput(ch: Name);
///         join PJoin(ch1: Name, ch2: Name);
///     }
/// }
/// ```
#[derive(Debug, Clone, Copy)]
pub struct JoinPatternDef {
    /// The constructor label this join pattern refers to.
    pub label: &'static str,

    /// The categories of the constructor's channel-binding parameters,
    /// in declaration order. Length ≥ 2 activates M8 (Multi-Tape
    /// Automata) in the dispatch pipeline.
    pub channel_categories: &'static [&'static str],
}

/// A logical connective declaration from `guards { connectives { } }`.
///
/// Each entry maps a connective role to its surface keyword spellings.
/// The role names are a closed set: `"and"`, `"or"`, `"not"`,
/// `"entails"`, `"implied_by"`, `"iff"`, `"forall"`, `"exists"`.
///
/// Example source:
/// ```text
/// guards {
///     connectives {
///         and = "and" | "∧";
///         not = "not" | "¬";
///     }
/// }
/// ```
#[derive(Debug, Clone, Copy)]
pub struct ConnectiveDef {
    /// The connective role as a stable identifier (one of the eight
    /// names above).
    pub role: &'static str,

    /// The surface keywords that spell this connective in the guard
    /// sublanguage (e.g., `["and", "∧"]` for the `"and"` role).
    pub keywords: &'static [&'static str],
}

// ═════════════════════════════════════════════════════════════════════════════
// Backward-compatibility tests
// ═════════════════════════════════════════════════════════════════════════════

#[cfg(test)]
mod guard_metadata_tests {
    use super::*;

    /// A minimal `LanguageMetadata` impl that overrides only the
    /// required methods. All guard-related methods should return empty
    /// slices via the trait defaults — this test verifies backward
    /// compatibility with languages that have no `guards { }` block.
    struct MinimalMeta;

    static TEST_TYPE: TypeDef = TypeDef {
        name: "T",
        native_type: None,
        is_primary: true,
    };

    impl LanguageMetadata for MinimalMeta {
        fn name(&self) -> &'static str {
            "Minimal"
        }
        fn types(&self) -> &'static [TypeDef] {
            std::slice::from_ref(&TEST_TYPE)
        }
        fn terms(&self) -> &'static [TermDef] {
            &[]
        }
        fn equations(&self) -> &'static [EquationDef] {
            &[]
        }
        fn rewrites(&self) -> &'static [RewriteDef] {
            &[]
        }
    }

    #[test]
    fn default_empty_guard_metadata() {
        let m = MinimalMeta;
        assert!(m.builtin_predicates().is_empty());
        assert!(m.theories().is_empty());
        assert!(m.channels().is_empty());
        assert!(m.join_patterns().is_empty());
        assert!(m.connectives().is_empty());
        assert_eq!(m.runtime_backends(), NO_RUNTIME_BACKEND_CAPABILITIES);
    }

    /// A metadata impl that returns non-empty guard data. Verifies the
    /// types round-trip correctly.
    struct RichMeta;

    static RICH_TYPE: TypeDef = TypeDef {
        name: "Proc",
        native_type: None,
        is_primary: true,
    };
    static RICH_PREDS: &[BuiltinPredicateDef] = &[BuiltinPredicateDef {
        name: "eq",
        syntax: "x \"==\" y",
        selectivity: Some(0.1),
        cost: Some(2),
    }];
    static RICH_THEORIES: &[TheoryDef] = &[TheoryDef {
        name: "arithmetic",
        theory_type: "PresburgerAlgebra",
        handled_types: &["Int"],
    }];
    static RICH_CHANNELS: &[ChannelDef] = &[ChannelDef { category: "Name" }];
    static RICH_JOINS: &[JoinPatternDef] = &[JoinPatternDef {
        label: "PGuardedInput",
        channel_categories: &["Name"],
    }];
    static RICH_CONNECTIVES: &[ConnectiveDef] =
        &[ConnectiveDef { role: "and", keywords: &["and", "∧"] }];
    static RICH_EQUATIONS: &[EquationDef] = &[EquationDef {
        conditions: &[],
        lhs: "lhs",
        rhs: "rhs",
        is_guarded: false,
    }];
    static RICH_REWRITES: &[RewriteDef] = &[RewriteDef {
        name: Some("step"),
        conditions: &[],
        premise: None,
        lhs: "redex",
        rhs: "contractum",
        is_guarded: true,
    }];
    static RICH_BACKENDS: &[BackendCapabilityDef] = &[
        BackendCapabilityDef {
            backend: RuntimeBackend::RhoMachine,
            is_default: true,
        },
        BackendCapabilityDef {
            backend: RuntimeBackend::Ascent,
            is_default: false,
        },
    ];

    impl LanguageMetadata for RichMeta {
        fn name(&self) -> &'static str {
            "Rich"
        }
        fn definition_fingerprint(&self) -> Option<&'static str> {
            Some("rich-fingerprint")
        }
        fn types(&self) -> &'static [TypeDef] {
            std::slice::from_ref(&RICH_TYPE)
        }
        fn terms(&self) -> &'static [TermDef] {
            &[]
        }
        fn equations(&self) -> &'static [EquationDef] {
            RICH_EQUATIONS
        }
        fn rewrites(&self) -> &'static [RewriteDef] {
            RICH_REWRITES
        }
        fn builtin_predicates(&self) -> &'static [BuiltinPredicateDef] {
            RICH_PREDS
        }
        fn theories(&self) -> &'static [TheoryDef] {
            RICH_THEORIES
        }
        fn channels(&self) -> &'static [ChannelDef] {
            RICH_CHANNELS
        }
        fn join_patterns(&self) -> &'static [JoinPatternDef] {
            RICH_JOINS
        }
        fn connectives(&self) -> &'static [ConnectiveDef] {
            RICH_CONNECTIVES
        }
        fn runtime_backends(&self) -> &'static [BackendCapabilityDef] {
            RICH_BACKENDS
        }
    }

    #[test]
    fn rich_metadata_roundtrip() {
        let m = RichMeta;
        assert_eq!(m.builtin_predicates().len(), 1);
        assert_eq!(m.builtin_predicates()[0].name, "eq");
        assert_eq!(m.builtin_predicates()[0].selectivity, Some(0.1));
        assert_eq!(m.theories().len(), 1);
        assert_eq!(m.theories()[0].theory_type, "PresburgerAlgebra");
        assert_eq!(m.theories()[0].handled_types, &["Int"]);
        assert_eq!(m.channels().len(), 1);
        assert_eq!(m.channels()[0].category, "Name");
        assert_eq!(m.join_patterns().len(), 1);
        assert_eq!(m.join_patterns()[0].label, "PGuardedInput");
        assert_eq!(m.connectives().len(), 1);
        assert_eq!(m.connectives()[0].role, "and");
        assert_eq!(m.connectives()[0].keywords, &["and", "∧"]);
        assert_eq!(m.runtime_backends(), RICH_BACKENDS);
        assert_eq!(m.runtime_backends()[0].backend, RuntimeBackend::RhoMachine);
        assert!(m.runtime_backends()[0].is_default);
    }

    #[test]
    fn default_automata_model_is_derived_from_metadata() {
        let m = MinimalMeta;
        let model = m.automata_model();
        assert_eq!(model.categories.len(), 1);
        assert_eq!(model.categories[0].name, "T");
        assert_eq!(model.semantic_rule_count(), 0);
        assert_eq!(model.guard_surface_count(), 0);
        assert!(!model.has_guarded_runtime_rules());
        assert!(!model.has_definition_identity());
    }

    #[test]
    fn rich_automata_model_preserves_identity_rules_and_guard_surfaces() {
        let m = RichMeta;
        let model = m.automata_model();
        assert_eq!(model.definition_fingerprint, Some("rich-fingerprint"));
        assert_eq!(model.semantic_rule_count(), 2);
        assert_eq!(model.guard_surface_count(), 4);
        assert!(model.has_guarded_runtime_rules());
        assert!(model.has_definition_identity());
        assert_eq!(model.rewrites[0].name, Some("step"));
    }
}
